CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK (length(full_name)<=100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING (auth.uid()=id) WITH CHECK (auth.uid()=id);
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES (new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),100)); RETURN new; END; $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone) BETWEEN 5 AND 30), line1 text NOT NULL CHECK(length(line1) BETWEEN 1 AND 200), line2 text NOT NULL DEFAULT '' CHECK(length(line2)<=200), city text NOT NULL CHECK(length(city) BETWEEN 1 AND 100), region text NOT NULL CHECK(length(region) BETWEEN 1 AND 100), postal_code text NOT NULL CHECK(length(postal_code) BETWEEN 1 AND 20), country text NOT NULL CHECK(length(country) BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.addresses TO authenticated;
GRANT ALL ON public.addresses TO service_role;
ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_addresses ON public.addresses FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.shopping_bags (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, items jsonb NOT NULL DEFAULT '[]', wishlist jsonb NOT NULL DEFAULT '[]');
GRANT SELECT, INSERT, UPDATE ON public.shopping_bags TO authenticated;
GRANT ALL ON public.shopping_bags TO service_role;
ALTER TABLE public.shopping_bags ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_bag ON public.shopping_bags FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, request_id uuid NOT NULL, items jsonb NOT NULL, shipping_address jsonb NOT NULL, subtotal integer NOT NULL CHECK(subtotal>0), shipping integer NOT NULL CHECK(shipping>=0), total integer NOT NULL CHECK(total=subtotal+shipping), payment_method text NOT NULL CHECK(payment_method='cod'), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')), status text NOT NULL DEFAULT 'placed' CHECK(status IN ('placed','processing','shipped','delivered','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_id));
GRANT SELECT ON public.orders TO authenticated;
GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_orders ON public.orders FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE INDEX orders_customer_date ON public.orders(user_id,created_at DESC);
CREATE INDEX addresses_customer ON public.addresses(user_id);
CREATE FUNCTION public.place_cod_order(p_request_id uuid,p_items jsonb,p_address jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); oid uuid; entry jsonb; idx integer; qty integer; amount integer:=0; fee integer; lines jsonb:='[]'; prices integer[]:=ARRAY[2800,2600,2700,2900,2800,2600]; names text[]:=ARRAY['Velvet Rouge','Nude Cashmere','Rose Silk','Champagne Veil','Midnight Noir','Pearl Ivory']; k text;
BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to place your order'; END IF;
SELECT id INTO oid FROM public.orders WHERE user_id=uid AND request_id=p_request_id; IF oid IS NOT NULL THEN RETURN oid; END IF;
IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Invalid bag'; END IF;
FOR entry IN SELECT value FROM jsonb_array_elements(p_items) LOOP
idx:=(entry->>'productId')::integer; qty:=(entry->>'quantity')::integer;
IF idx NOT BETWEEN 0 AND 5 OR qty NOT BETWEEN 1 AND 20 OR idx IS NULL OR qty IS NULL THEN RAISE EXCEPTION 'Invalid item'; END IF;
IF EXISTS (SELECT 1 FROM jsonb_array_elements(lines) x WHERE (x->>'productId')::integer=idx) THEN RAISE EXCEPTION 'Duplicate item'; END IF;
amount:=amount+prices[idx+1]*qty;
lines:=lines||jsonb_build_array(jsonb_build_object('productId',idx,'name',names[idx+1],'quantity',qty,'unitPrice',prices[idx+1]));
END LOOP;
IF jsonb_typeof(p_address)<>'object' THEN RAISE EXCEPTION 'Invalid shipping address'; END IF;
FOREACH k IN ARRAY ARRAY['full_name','phone','line1','city','region','postal_code','country'] LOOP IF length(trim(coalesce(p_address->>k,''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Shipping details incomplete'; END IF; END LOOP;
IF length(coalesce(p_address->>'line2',''))>200 THEN RAISE EXCEPTION 'Invalid address'; END IF;
fee:=CASE WHEN amount>6000 THEN 0 ELSE 500 END;
INSERT INTO public.orders(user_id,request_id,items,shipping_address,subtotal,shipping,total,payment_method) VALUES(uid,p_request_id,lines,p_address,amount,fee,amount+fee,'cod') ON CONFLICT(user_id,request_id) DO NOTHING RETURNING id INTO oid;
IF oid IS NULL THEN SELECT id INTO oid FROM public.orders WHERE user_id=uid AND request_id=p_request_id; END IF;
UPDATE public.shopping_bags SET items='[]' WHERE user_id=uid;
RETURN oid;
END; $$;
REVOKE ALL ON FUNCTION public.place_cod_order(uuid,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.place_cod_order(uuid,jsonb,jsonb) TO authenticated;